//! Marge's radio lines, generated from the browser's tables
//! (src/js/04-dispatcher-radio.js and the fixed lines it passes at call
//! sites) by native/tools/gen_lines.cjs. Do not edit by hand.

use cj_sim::events::Radio;

/// The stock lines for a radio key. Keys whose lines are always built by
/// the simulation (with this moment's numbers) have none.
pub fn lines(key: Radio) -> &'static [&'static str] {
    match key {
        Radio::Start => &["Morning, hotshot. Five minutes on the clock. Bring me something worth the fuel.", "Shift is live, kiddo. Remember, the tug is collateral. So are you.", "Coffee is cold, my knees hurt, and you are on the clock. Go make money."],
        Radio::Hook => &["Hooked. Mind the swing.", "That is on the line. Try not to lose it this time.", "Winch is holding. For now."],
        Radio::Heavy => &["You are towing a small moon. Turning is a suggestion now.", "Engines are complaining. Join the club."],
        Radio::Maxed => &["Winch is full, sugar. Bank something or cut something."],
        Radio::Reactor => &["You hooked a reactor core. Do not shoot the reactor core.", "Reactor on the line. One hard bump and it blows. Fly like your grandmother. Not mine. Mine was a menace."],
        Radio::Engine => &["Engine block. Seven tonnes of bad decisions waiting to happen."],
        Radio::Jumper => &["Claim jumper on scope. They want your haul. Rude.", "Pink contact inbound. Rival crew. They are not here to make friends."],
        Radio::SentriesRogue => &["Tug is down, and your sentries just lost their link. They are shooting at everything now. Including you, hotshot."],
        Radio::RogueDown => &["Rogue sentry down. It dropped its core. Careful: those bite, and they go off if you bang them around."],
        Radio::Latched => &["They have a line on your cargo. Shoot them, or swing something heavy at their face."],
        Radio::Severed => &["They cut your line. That was our money, hotshot.", "Line severed. Go get it back. I will wait. I always wait."],
        Radio::Escaped => &["And it is gone. I am logging that as tuition.", "They got away with it. Insurance says that was your fault. So do I."],
        Radio::Crab => &["Crab on your cable. Yank the line hard and shake it off.", "Something is crawling up your tow line. Give it a good jerk."],
        Radio::CrabHull => &["Crab on the hull. Spin the tug and throw it off, or limp home to the bay."],
        Radio::CrabOff => &["Crab overboard. Nice spin. Do not let it go to your head."],
        Radio::Bank => &["Banked.", "Bay crew says thanks. They are lying, but they said it.", "Logged. The loan officer almost smiled.", "Into the bay it goes. Slowly. Like my pension."],
        Radio::BankBig => &["Now that pays the interest. Some of it.", "Well, look at you. I might even approve your lunch break."],
        Radio::HullLow => &["Hull is under thirty percent. Insurance already said no."],
        Radio::Dead => &["Tug is down. The deductible comes out of your pay. Again. Respawning at the bay."],
        Radio::Refinery => &["Sensor ping. The old Kessler ore works is drifting through. Nobody ever cracked that vault. Nobody ever had your nerve, or your debt.", "Big contact. The Kessler refinery. Vault is still sealed, and still full. Do not get greedy. Who am I kidding."],
        Radio::RefineryHint => &["There are mining charges floating by the station. Tow them into the three sockets around the vault. Gently, hon."],
        Radio::Drones => &["Security drones are waking up. The station still thinks it is on payroll. Must be nice.", "Station security is online. Mind those charges. One hit and you are a postcard."],
        Radio::Armed => &["All three seated. Five seconds. Get clear of the vault."],
        Radio::Vault => &["Vault is open. That is a fortune in refined ore. Grab it and go."],
        Radio::Jaws => &["Uh. The jaws are moving. It is eating the field. Do not get eaten. I am not training a replacement.", "Processing jaws are awake. It is pulling everything in. Including you, genius."],
        Radio::JawsShip => &["You are in the jaws. Full thrust, or cut the load. Now."],
        Radio::AteCargo => &["It ate your cargo. That station owes us money now. Good luck collecting."],
        Radio::Miners => &["Heads up. Automated mining drones are still working the old Kessler contract. They cut rock and fling it everywhere. Like my ex.", "Mining drones on scope. They do not care what is in the way. Their ore spills are free money, though."],
        Radio::Storm => &["Debris storm by the miners. Those pebbles are moving fast.", "You are in their blast zone. Fast rock incoming. Duck. Figuratively."],
        Radio::MinerAngry => &["You shot a miner. Now it is drilling you. Shocking.", "That miner is pointing its cutter at you. Back off, or finish the job."],
        Radio::MinerKill => &["Miner down. Its ore hopper just burst open.", "Scrapped a miner. Grab the ore before somebody else does."],
        Radio::Collector => &["Debt collector on scope. They do not want the cargo. They want the tug.", "Kessler Mutual Recovery is here. And our payment is not even late. Yet."],
        Radio::Netted => &["You are netted. Hard left, hard right, tear it. Or shoot that thing.", "They got a net on you. Wiggle out before they tow you off the field."],
        Radio::NetFree => &["Net is torn. Now get away from that man.", "You are loose. Do not let them line up another shot, sugar."],
        Radio::CollectorKill => &["Collector down. Legally, I never saw that.", "Scrapped a repo man. That plating is worth something. Unlike him."],
        Radio::Greedy => &["That collector just went greedy. They are not here for your payment anymore. They want your haul."],
        Radio::CollectorLeaves => &["Collector is leaving. Your numbers check out, for once."],
        Radio::NetEdge => &["They are almost at the edge with you. Break free. Now."],
        Radio::FatCable => &["That is a fat cable. Kessler Mutual noticed. Collector inbound, and they will take the load if they catch you.", "You are hauling a fortune, and the bank can smell it. Collector on the way. Get it home."],
        Radio::DroneKill => &["Drone down. Kessler Security can send me the bill. I will lose it."],
        Radio::RivalsAnnoyed => &["You keep scrapping their people. The rival crews are annoyed now. They will shoot while they steal."],
        Radio::RivalsHostile => &["The rival crews have a grudge, kiddo. Some of them are coming for you now, not the cargo."],
        Radio::RivalsVendetta => &["Congratulations. It is a vendetta. They hunt in pairs now. I am updating your obituary."],
        Radio::Hunter => &["Rival inbound, and that one is not here for cargo. It is here for you.", "Hunter on scope. Somebody holds a grudge, hotshot."],
        Radio::WantedMore => &["Another collector? Your wanted level just went up again. The sheriff reads the same reports I do."],
        Radio::SheriffPatrol => &["Sheriff patrol in the field. Keep your nose clean, for once."],
        Radio::SheriffWanted => &["Sheriff patrol inbound, and you are wanted. Keep your distance."],
        Radio::Pursuit => &["The sheriff spotted you. Run, or get cuffed. Do not let him get close.", "Lights and sirens, kiddo. He is on you. Keep moving."],
        Radio::LostSheriff => &["You lost him. For now. He will be back, they always are."],
        Radio::SheriffShotAt => &["Watch your fire, hotshot. That is the sheriff. Hit him all you like, but if he goes down, you are wanted."],
        Radio::Reinforcements => &["More law inbound. They are bringing friends.", "Backup is on the way, and it is not yours."],
        Radio::Swat => &["Five stars. That is the Galactic SWAT team. Live rounds, hotshot. Run. Very. Fast."],
        Radio::Shakedown => &["The sheriff is shaking you down. No warrant, no reason, he just wants your cargo. Run, or lose it."],
        Radio::SheriffKill => &["You shot down the sheriff. Two more stars. I am not bailing you out."],
        Radio::ShieldDown => &["Shields are down. Hull is next, hotshot.", "There go your shields. Try not getting hit. Novel idea."],
        Radio::MissilesLive => &["Missile rack is live. It shoots first and never asks."],
        Radio::Overheat => &["Heat sink is cooked. Guns and thrusters are locked until it cools. Like you should be.", "You are overheating. Ease off the trigger, hotshot."],
        Radio::Grind => &["Ground it into slugs. Accounting just wept.", "Grinder fed. Sale value, zero. Ammo, plenty. I hate it here."],
        Radio::GrindReactor => &["You put a reactor in the grinder? A reactor. In the grinder."],
        Radio::Scooped => &["Scoop caught something. Free money, probably."],
        Radio::Kill => &["Jumper scrapped. Their parts spend like anybody else's.", "One less pink dot. Grab what fell off."],
        Radio::Smash => &["You hit him with an engine. That is going in the newsletter.", "Cargo-based diplomacy. I approve."],
        Radio::Boom => &["That was a reactor. Was. Past tense.", "Reactor blew. Count your fingers. Then count the cargo."],
        Radio::Cut => &["Cut loose. Your cargo, your call. Your mistake."],
        Radio::Minute => &["One minute left. Bring it home."],
        Radio::TenSec => &["Ten seconds. Bay doors are closing."],
        Radio::NewWreck => &["New derelict drifting into the field. Fresh pickings."],
        Radio::Repair => &["Bay crew is patching you up. Hold still, you are not that interesting."],
        Radio::CoreZap => &["That core is still angry. It will bite you every so often until it is in the bay."],
        Radio::EngineOverheat => &["You cooked the engine, hotshot. Six seconds of crawling while it cools. Ease off the burners."],
        Radio::JawsWrecked => &["You broke the jaws. Somebody at Kessler is going to cry about that. It won't be me."],
        Radio::EscortDone => &["Hauler is docked. Not a scratch on it. Well, a few scratches. Nobody is counting."],
        Radio::EscortLow => &["The hauler is coming apart, hon. Get those crews off it."],
        Radio::EscortLost => &["We lost the hauler. That is going to be an awkward phone call."],
        Radio::IonClear => &["Ion storm has passed. Shields are coming back up. Slowly. Like everything else around here."],
        Radio::IonStorm => &["Ion storm rolling through. Your shields are gone until it passes. Fly like you mean it."],
        Radio::Derelict => &["Derelict freighter on scope. Hold full of salvage and nobody aboard. Every crew in the belt heard that too."],
        Radio::Scatter => &["Ha. Look at them run. Nobody wants to be next under that cargo."],
        Radio::HoldOpen => &["Hold is open. Ingots, an engine, maybe a reactor. Somebody locked that up for a reason. Take it anyway."],
        Radio::HoldSealed => &["That hold is sealed tight, hotshot. There is a keycard floating around out there. Tow it in."],
        Radio::Sanctuary => &["Carrier's private property, hotshot. The law can't touch you in here. Your record's clean. For now."],
        Radio::Escort => &["Freight hauler inbound, headed for our bay, and every crew in the belt can see it. Keep them off it, hotshot."],
        _ => &[],
    }
}

/// The cockpit warning callout said before Marge's line on urgent keys.
pub fn callout(key: Radio) -> Option<&'static str> {
    Some(match key {
        Radio::IonStorm => "Warning. Ion storm.",
        Radio::Boss => "Warning. Bounty target.",
        Radio::Derelict => "Contact. Derelict freighter.",
        Radio::SentriesRogue => "Warning. Rogue drones.",
        Radio::HullLow => "Warning. Hull integrity.",
        Radio::Dead => "Hull failure.",
        Radio::CrabHull => "Warning. Hull breach.",
        Radio::Netted => "Warning. Net. Net.",
        Radio::NetEdge => "Warning. Field boundary.",
        Radio::Collector => "Caution. Debt collector.",
        Radio::Greedy => "Warning. Hostile collector.",
        Radio::FatCable => "Caution. Debt collector.",
        Radio::LowWallet => "Caution. Payment shortfall.",
        Radio::Confiscated => "Cargo confiscated.",
        Radio::Latched => "Caution. Cargo tether.",
        Radio::Severed => "Cable severed.",
        Radio::Jaws => "Warning. Proximity.",
        Radio::JawsShip => "Pull out. Pull out.",
        Radio::Armed => "Charges armed.",
        Radio::Overheat => "Overheat. Overheat.",
        Radio::Minute => "One minute.",
        Radio::TenSec => "Ten seconds.",
        Radio::ShieldDown => "Shields down.",
        Radio::Pursuit => "Warning. Law enforcement.",
        Radio::SheriffWanted => "Caution. Sheriff patrol.",
        Radio::Hunter => "Caution. Hostile contact.",
        Radio::Swat => "Warning. Warning. SWAT.",
        Radio::Reinforcements => "Caution. Additional units.",
        Radio::Shakedown => "Warning. Law enforcement.",
        Radio::Arrested => "Arrested.",
        _ => return None,
    })
}

/// What Marge mutters before a routine line, about a third of the time.
pub const ASIDES: [&str; 8] = [
    "Hmph.",
    "Mm.",
    "Oh, sugar.",
    "Lord.",
    "Well.",
    "Kiddo.",
    "Sweetheart.",
    "Uh-huh.",
];
